# ---------------------------------------------------------------- 部品
PAIR = ("detail", "init", "cond", "valid", "ex", "open", "demo_ok", "chk")


def F(no, ja, sel, kind, trig="view", **kw):
    d = {"no": no, "ja": ja, "vi": "", "sel": sel, "kind": kind, "trig": trig}
    for k, v in kw.items():
        if v is None:
            continue
        if k in PAIR and isinstance(v, str):
            v = [v, ""]
        if k == "len" and isinstance(v, str):
            v = [v, ""]
        d[k] = v
    return d


def ST(vid, code, state, note, items, url, **kw):
    su = kw.pop("setup", "")
    # どの状態も先にデータを見本に戻す（前の状態の操作を引きずらない）
    su = su[len(JS):] if su.startswith(JS) else su
    su = JS + "const U=%s;await rs();" % json.dumps(url, ensure_ascii=False) + su
    d = {"id": vid, "code": code, "state": [state, ""], "url": url, "setup": su, "full": kw.pop("full", False), "wait": kw.pop("wait", 600),
         "note": [note, ""], "items": items}
    d.update(kw)
    return d


