JS = ("const sleep=ms=>new Promise(r=>setTimeout(r,ms));"
      "const setv=(el,v)=>{const p=el.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;"
      "Object.getOwnPropertyDescriptor(p,'value').set.call(el,v);el.dispatchEvent(new Event('input',{bubbles:true}));};"
      "const sets=(el,v)=>{Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value').set.call(el,v);el.dispatchEvent(new Event('change',{bubbles:true}));};"
      "const btn=t=>[...document.querySelectorAll('button')].find(b=>b.textContent.replace(/\\s+/g,'').includes(t));"
      "const tab=t=>[...document.querySelectorAll('.es-tab')].find(b=>b.textContent.replace(/\\s+/g,'').includes(t));"
      "const q=s=>document.querySelector(s);"
      "const wb=async t=>{for(let k=0;k<40;k++){const b=btn(t);if(b)return b;await sleep(100);}return null;};"   # 権限の読み込みを待ってからボタンを探す
      "const wsb=async t=>{for(let k=0;k<40;k++){const b=sb(t);if(b)return b;await sleep(100);}return null;};"
      "const sb=t=>[...document.querySelectorAll('.es-selbar__actions button')].find(b=>b.textContent.replace(/\\s+/g,'').includes(t));"
      "const okm=async()=>{const b=q('.es-modal__actions .es-btn--solid');if(b){b.click();await sleep(500);}};"
      "const opt=(sel,t)=>{const o=[...sel.options].find(x=>x.textContent.includes(t));return o?o.value:'';};"
      "const pick=async(i,t)=>{const s=document.querySelectorAll('.es-search__fields select')[i];if(!s)return;sets(s,opt(s,t));await sleep(150);};"
      "const apply=async()=>{const b=[...document.querySelectorAll('.es-search__actions button')].find(x=>x.textContent.includes('検索'));if(b){b.click();await sleep(500);}};"
      # データを見本に戻す・API で前の操作を再現する（撮影は状態ごとに独立させる。画面は visibilitychange で読み直させる）
      "const call=async(op,a)=>{const r=await fetch('/api/ops/area/billing/'+op,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json','x-es-site':'ops'},body:JSON.stringify({args:a??null})});const t=await r.text();try{return JSON.parse(t);}catch(e){return t;}};"
      "const go=async()=>{const r=window.next&&window.next.router;if(!r)return;r.push('/ops/billing/collection');await sleep(800);r.push(U);"
      "for(let k=0;k<60;k++){const h=q('.es-pagehead__title');if((h&&!/集金管理/.test(h.textContent))||q('.es-inline--warning'))break;await sleep(100);}await sleep(900);};"   # 別の画面へ移って戻す（データを読み直させる）
      "const rl=go;"
      "const rs=async()=>{await fetch('/api/dev/reset',{method:'POST',credentials:'include'});await sleep(700);await go();};")
# 検索（状態の選択肢は 0 締め月・1 状態・2 先月からの変更・3 支払方法 の順。コードの画面にある選択だけ）
PICK = lambda i, t: JS + "await pick(%d,'%s');await apply();" % (i, t)
# 前の操作を API で再現する（状態ごとに独立。コードの画面の言い方：子契約の確定待ち／請求書を作成できます／作成済み・未発行／発行済）
