DS1 = MK1 + "await call('dispatch',{id:'INV-2026110001'});"            # → 発行済（Bill One：送付待ち）
ERR3 = ("await call('confirmFix',{id:'CU00671'});await call('makeInvoice',{co:'CU00003',br:'CU00671'});"
        "await call('dispatch',{id:'INV-2026110001'});")                  # 大阪キッチン：1回目の発行は送信エラー
# 操作 → 画面を読み直す → 状態で絞る
OPS = lambda ops, i=None, t="": JS + ops + "await rl();" + ("await pick(%d,'%s');await apply();" % (i, t) if i is not None else "")
