def _fill(o, name=""):
    if isinstance(o, dict):
        n = o.get("ja", name) if isinstance(o.get("ja"), str) else name
        for k, v in o.items():
            if isinstance(v, list) and len(v) == 2 and all(isinstance(x, str) for x in v):
                if v[0] and not v[1]:
                    v[1] = _VI_EX.get((n, v[0])) if k == "ex" else None
                    if not v[1]:
                        v[1] = _VI.get(v[0], "")
            elif k == "vi" and isinstance(v, str) and not v and isinstance(o.get("ja"), str):
                o[k] = _VI.get(o["ja"], "")
            elif isinstance(v, (dict, list, tuple)):
                _fill(v, n)
    elif isinstance(o, (list, tuple)):
        for x in o:
            _fill(x, name)


