def _view(vid):
    return next(v for v in VIEWS if v["id"] == vid)


def _na(vid, why=""):
    v = _view(vid)
    old = v["note"][0]
    if old.startswith("【撮影不可】"):
        return
    new = "【撮影不可】" + old
    _VI[new] = "【Không thể chụp】" + _VI.get(old, "")
    v["note"][0] = new
    v["note"][1] = ""


def _noshot(vid, nos, why=NOSHOT, force=False):
    for it in _view(vid)["items"]:
        if it["no"] in nos:
            it["sel"] = "-"
            if force or "demo_ok" not in it:
                it["demo_ok"] = [why, ""]


def _set(vid, ops="", url=None, **kw):
    """状態の作り方：データを見本に戻す → 前の操作を API で再現（ops）→ 画面を操作。url を変えるときは url に"""
    v = _view(vid)
    if url:
        v["url"] = url
    v["setup"] = JS + "const U=%s;await rs();" % json.dumps(v["url"], ensure_ascii=False) + ops
    v.update(kw)


def _sel(vid, no, sel):
    for it in _view(vid)["items"]:
        if it["no"] == no:
            it["sel"] = sel


